-- Gold Query
SELECT t1.player_name FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE t2.potential = '61' ORDER BY t2.balance DESC, t1.id NULLS LAST, t2.id NULLS LAST LIMIT 1;

/*
Gold Result:
('Sandra Zimmerman',)
*/

-- Prediction Query
SELECT DISTINCT player_name FROM Player AS p JOIN Player_Attributes AS pa ON p.player_api_id = pa.player_api_id WHERE pa.potential = 61 AND pa.balance = (SELECT MAX(balance) FROM Player_Attributes WHERE potential = 61);

/*
Prediction Result:
('Sandra Zimmerman',)
('Daniel Salinas',)
*/